1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { normalizeAreas } from "./team-areas";
7	
8	/**
9	 * Teams / Organizations — shared-account server actions.
10	 *
11	 * An Organization has one owner (User "OrgOwner") plus a set of Memberships.
12	 * Every actor is verified to hold a Membership of the required role in the
13	 * target org before any mutation runs, so a hand-crafted request can't touch
14	 * an org the caller doesn't belong to.
15	 *
16	 * SCOPE: this covers org + membership CRUD only. Shared billing (org wallet /
17	 * invoices) and members inheriting access to shared servers are deliberately
18	 * OUT OF SCOPE and left as follow-ups — nothing here changes server ownership.
19	 */
20	
21	const ROLES = ["OWNER", "ADMIN", "MEMBER", "BILLING"] as const;
22	type OrgRole = (typeof ROLES)[number];
23	
24	function isRole(v: string): v is OrgRole {
25	  return (ROLES as readonly string[]).includes(v);
26	}
27	
28	/** Roles allowed to administer membership (invite / change roles / remove). */
29	function canAdminister(role: string): boolean {
30	  return role === "OWNER" || role === "ADMIN";
31	}
32	
33	/** Load the actor's membership in an org, or null if they aren't a member. */
34	async function actorMembership(orgId: string, userId: string) {
35	  if (!orgId) return null;
36	  return db.membership.findUnique({
37	    where: { orgId_userId: { orgId, userId } },
38	  });
39	}
40	
41	/**
42	 * Create an organization owned by the current user, plus an OWNER membership
43	 * for the creator. Consumed via `useActionState`.
44	 */
45	export async function createOrg(
46	  _prev: unknown,
47	  formData: FormData,
48	): Promise<{ error?: string; ok?: boolean }> {
49	  const user = await requireUser();
50	  const name = String(formData.get("name") ?? "").trim();
51	  if (name.length < 2 || name.length > 60) {
52	    return { error: "Organization name must be 2–60 characters." };
53	  }
54	
55	  await db.organization.create({
56	    data: {
57	      name,
58	      ownerId: user.id,
59	      members: {
60	        create: { userId: user.id, role: "OWNER" },
61	      },
62	    },
63	  });
64	
65	  await db.auditLog.create({
66	    data: { userId: user.id, action: "org.created", detail: name },
67	  });
68	  revalidatePath("/dashboard/team");
69	  return { ok: true };
70	}
71	
72	/**
73	 * Invite a teammate by email. Only OWNER/ADMIN of the org may invite.
74	 * If a user account with that email exists, a Membership is created; otherwise
75	 * a clear message is returned (invitations to non-accounts are a follow-up).
76	 */
77	export async function inviteMember(
78	  orgId: string,
79	  email: string,
80	  role: string,
81	): Promise<{ error?: string; ok?: boolean; message?: string }> {
82	  const user = await requireUser();
83	  const normalizedEmail = String(email ?? "").trim().toLowerCase();
84	  if (!normalizedEmail || !normalizedEmail.includes("@")) {
85	    return { error: "Enter a valid email address." };
86	  }
87	  const wantRole = String(role ?? "MEMBER").toUpperCase();
88	  if (!isRole(wantRole) || wantRole === "OWNER") {
89	    // OWNER is assigned only at creation / ownership transfer, never via invite.
90	    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
91	  }
92	
93	  const actor = await actorMembership(orgId, user.id);
94	  if (!actor || !canAdminister(actor.role)) {
95	    return { error: "You don't have permission to invite members to this organization." };
96	  }
97	
98	  const invitee = await db.user.findUnique({ where: { email: normalizedEmail } });
99	  if (!invitee) {
100	    return {
101	      message: `No account with that email yet — ${normalizedEmail} needs to sign up first, then you can add them.`,
102	    };
103	  }
104	
105	  const existing = await actorMembership(orgId, invitee.id);
106	  if (existing) {
107	    return { error: "That person is already a member of this organization." };
108	  }
109	
110	  await db.membership.create({
111	    data: { orgId, userId: invitee.id, role: wantRole },
112	  });
113	  await db.auditLog.create({
114	    data: { userId: user.id, action: "org.member_invited", detail: `${normalizedEmail} → ${wantRole}` },
115	  });
116	  revalidatePath("/dashboard/team");
117	  return { ok: true, message: `${invitee.name} added as ${wantRole.toLowerCase()}.` };
118	}
119	
120	/**
121	 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
122	 * pinned to OWNER and cannot be downgraded here.
123	 */
124	export async function updateMemberRole(
125	  orgId: string,
126	  userId: string,
127	  role: string,
128	): Promise<{ error?: string; ok?: boolean }> {
129	  const user = await requireUser();
130	  const wantRole = String(role ?? "").toUpperCase();
131	  if (!isRole(wantRole) || wantRole === "OWNER") {
132	    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
133	  }
134	
135	  const actor = await actorMembership(orgId, user.id);
136	  if (!actor || !canAdminister(actor.role)) {
137	    return { error: "You don't have permission to change roles in this organization." };
138	  }
139	
140	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
141	  if (!org) return { error: "Organization not found." };
142	  if (userId === org.ownerId) {
143	    return { error: "The organization owner's role can't be changed." };
144	  }
145	
146	  const target = await actorMembership(orgId, userId);
147	  if (!target) return { error: "That person isn't a member of this organization." };
148	
149	  await db.membership.update({
150	    where: { orgId_userId: { orgId, userId } },
151	    data: { role: wantRole },
152	  });
153	  await db.auditLog.create({
154	    data: { userId: user.id, action: "org.member_role_changed", detail: `${userId} → ${wantRole}` },
155	  });
156	  revalidatePath("/dashboard/team");
157	  return { ok: true };
158	}
159	
160	/**
161	 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
162	 */
163	export async function removeMember(
164	  orgId: string,
165	  userId: string,
166	): Promise<{ error?: string; ok?: boolean }> {
167	  const user = await requireUser();
168	
169	  const actor = await actorMembership(orgId, user.id);
170	  if (!actor || !canAdminister(actor.role)) {
171	    return { error: "You don't have permission to remove members from this organization." };
172	  }
173	
174	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
175	  if (!org) return { error: "Organization not found." };
176	  if (userId === org.ownerId) {
177	    return { error: "The organization owner can't be removed." };
178	  }
179	
180	  await db.membership.deleteMany({ where: { orgId, userId } });
181	  await db.auditLog.create({
182	    data: { userId: user.id, action: "org.member_removed", detail: userId },
183	  });
184	  revalidatePath("/dashboard/team");
185	  return { ok: true };
186	}
187	
188	/**
189	 * Set a member's allowed dashboard areas. Only OWNER/ADMIN act. The owner's
190	 * membership always keeps full access and can't be constrained here. Invalid
191	 * or unknown area keys are dropped; the resulting list is persisted verbatim to
192	 * `Membership.areas` (an empty list means "no restricted areas"). Passing every
193	 * area key is equivalent to full access.
194	 */
195	export async function setMemberAreas(
196	  membershipId: string,
197	  areas: string[],
198	): Promise<{ error?: string; ok?: boolean }> {
199	  const user = await requireUser();
200	
201	  const target = await db.membership.findUnique({ where: { id: membershipId } });
202	  if (!target) return { error: "That membership no longer exists." };
203	
204	  const actor = await actorMembership(target.orgId, user.id);
205	  if (!actor || !canAdminister(actor.role)) {
206	    return { error: "You don't have permission to change access in this organization." };
207	  }
208	
209	  const org = await db.organization.findUnique({
210	    where: { id: target.orgId },
211	    select: { ownerId: true },
212	  });
213	  if (!org) return { error: "Organization not found." };
214	  if (target.role === "OWNER" || target.userId === org.ownerId) {
215	    return { error: "The organization owner always has full access." };
216	  }
217	
218	  const clean = normalizeAreas(areas);
219	  await db.membership.update({
220	    where: { id: membershipId },
221	    data: { areas: clean },
222	  });
223	  await db.auditLog.create({
224	    data: {
225	      userId: user.id,
226	      action: "org.member_areas_changed",
227	      detail: `${target.userId} → [${clean.join(", ")}]`,
228	    },
229	  });
230	  revalidatePath("/dashboard/team");
231	  return { ok: true };
232	}
233	
234	/**
235	 * Leave an organization. The owner can't leave their own org (they'd have to
236	 * transfer ownership first — a follow-up), everyone else may.
237	 */
238	export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
239	  const user = await requireUser();
240	
241	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
242	  if (!org) return { error: "Organization not found." };
243	  if (org.ownerId === user.id) {
244	    return { error: "As the owner you can't leave — transfer ownership or delete the organization instead." };
245	  }
246	
247	  const membership = await actorMembership(orgId, user.id);
248	  if (!membership) return { error: "You're not a member of this organization." };
249	
250	  await db.membership.deleteMany({ where: { orgId, userId: user.id } });
251	  await db.auditLog.create({
252	    data: { userId: user.id, action: "org.left", detail: orgId },
253	  });
254	  revalidatePath("/dashboard/team");
255	  return { ok: true };
256	}
