3	import { Fragment, useActionState, useState, useTransition } from "react";
4	import { Badge } from "@/components/ui/primitives";
5	import {
6	  createOrg,
7	  inviteMember,
8	  updateMemberRole,
9	  removeMember,
10	  leaveOrg,
11	} from "@/lib/actions-teams";
12	import MemberAreas from "@/components/customer/MemberAreas";
13	
14	export type OrgMemberView = {
15	  membershipId: string;
16	  userId: string;
17	  name: string;
18	  email: string;
19	  role: string;
20	  areas: string[] | null;
21	  isOwner: boolean;
22	  joinedAgo: string;
23	};
24	
25	export type OrgView = {
26	  id: string;
27	  name: string;
28	  createdAgo: string;
29	  ownerName: string;
30	  myRole: string;
31	  canAdminister: boolean;
32	  isOwner: boolean;
33	  members: OrgMemberView[];
34	};
35	
36	const ASSIGNABLE_ROLES = ["ADMIN", "MEMBER", "BILLING"] as const;
37	
38	function roleTone(role: string): "brand" | "green" | "amber" | "slate" {
39	  if (role === "OWNER") return "brand";
40	  if (role === "ADMIN") return "green";
41	  if (role === "BILLING") return "amber";
42	  return "slate";
43	}
44	
45	/* ---------------- Create org ---------------- */
46	
47	function CreateOrgForm() {
48	  const [state, action, pending] = useActionState(createOrg, {} as { error?: string; ok?: boolean });
49	  return (
50	    <form action={action} className="flex flex-wrap items-end gap-3">
51	      <div>
52	        <label className="label">Organization name</label>
53	        <input
54	          className="input w-64"
55	          name="name"
56	          required
57	          minLength={2}
58	          maxLength={60}
59	          placeholder="Acme Inc."
60	        />
61	      </div>
62	      <button className="btn-primary" disabled={pending}>
63	        {pending ? "Creating…" : "Create organization"}
64	      </button>
65	      {state?.error && <p className="w-full text-sm text-red-400">{state.error}</p>}
66	      {state?.ok && <p className="w-full text-sm text-emerald-400">Organization created.</p>}
67	    </form>
68	  );
69	}
70	
71	/* ---------------- Invite ---------------- */
72	
73	function InviteForm({ orgId }: { orgId: string }) {
74	  const [email, setEmail] = useState("");
75	  const [role, setRole] = useState<string>("MEMBER");
76	  const [pending, start] = useTransition();
77	  const [msg, setMsg] = useState<{ tone: "error" | "info" | "ok"; text: string } | null>(null);
78	
79	  function submit(e: React.FormEvent) {
80	    e.preventDefault();
81	    setMsg(null);
82	    start(async () => {
83	      const res = await inviteMember(orgId, email, role);
84	      if (res.error) setMsg({ tone: "error", text: res.error });
85	      else if (res.ok) {
86	        setMsg({ tone: "ok", text: res.message ?? "Member added." });
87	        setEmail("");
88	      } else if (res.message) setMsg({ tone: "info", text: res.message });
89	    });
90	  }
91	
92	  return (
93	    <form onSubmit={submit} className="flex flex-wrap items-end gap-3">
94	      <div>
95	        <label className="label">Invite by email</label>
96	        <input
97	          className="input w-64"
98	          type="email"
99	          value={email}
100	          onChange={(e) => setEmail(e.target.value)}
101	          required
102	          placeholder="teammate@example.com"
103	        />
104	      </div>
105	      <div>
106	        <label className="label">Role</label>
107	        <select className="input w-36" value={role} onChange={(e) => setRole(e.target.value)}>
108	          {ASSIGNABLE_ROLES.map((r) => (
109	            <option key={r} value={r}>
110	              {r.charAt(0) + r.slice(1).toLowerCase()}
111	            </option>
112	          ))}
113	        </select>
114	      </div>
115	      <button className="btn-primary" disabled={pending || !email}>
116	        {pending ? "Adding…" : "Add member"}
117	      </button>
118	      {msg && (
119	        <p
120	          className={`w-full text-sm ${
121	            msg.tone === "error"
122	              ? "text-red-400"
123	              : msg.tone === "ok"
124	                ? "text-emerald-400"
125	                : "text-amber-300"
126	          }`}
127	        >
128	          {msg.text}
129	        </p>
130	      )}
131	    </form>
132	  );
133	}
134	
135	/* ---------------- Row controls ---------------- */
136	
137	function RoleSelect({ orgId, member }: { orgId: string; member: OrgMemberView }) {
138	  const [pending, start] = useTransition();
139	  const [err, setErr] = useState<string | null>(null);
140	  return (
141	    <div className="flex flex-col items-start">
142	      <select
143	        className="input py-1 text-xs"
144	        defaultValue={member.role}
145	        disabled={pending}
146	        onChange={(e) => {
147	          const role = e.target.value;
148	          setErr(null);
149	          start(async () => {
150	            const res = await updateMemberRole(orgId, member.userId, role);
151	            if (res.error) setErr(res.error);
152	          });
153	        }}
154	      >
155	        {ASSIGNABLE_ROLES.map((r) => (
156	          <option key={r} value={r}>
157	            {r.charAt(0) + r.slice(1).toLowerCase()}
158	          </option>
159	        ))}
160	      </select>
161	      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
162	    </div>
163	  );
164	}
165	
166	function RemoveButton({ orgId, member }: { orgId: string; member: OrgMemberView }) {
167	  const [pending, start] = useTransition();
168	  const [err, setErr] = useState<string | null>(null);
169	  return (
170	    <div className="flex flex-col items-end">
171	      <button
172	        className="btn-danger px-3 py-1 text-xs"
173	        disabled={pending}
174	        onClick={() => {
175	          if (!window.confirm(`Remove ${member.name} from this organization?`)) return;
176	          setErr(null);
177	          start(async () => {
178	            const res = await removeMember(orgId, member.userId);
179	            if (res.error) setErr(res.error);
180	          });
181	        }}
182	      >
183	        {pending ? "…" : "Remove"}
184	      </button>
185	      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
186	    </div>
187	  );
188	}
189	
190	function LeaveButton({ orgId }: { orgId: string }) {
191	  const [pending, start] = useTransition();
192	  const [err, setErr] = useState<string | null>(null);
193	  return (
194	    <div className="flex flex-col items-end">
195	      <button
196	        className="btn-ghost px-3 py-1 text-xs"
197	        disabled={pending}
198	        onClick={() => {
199	          if (!window.confirm("Leave this organization?")) return;
200	          setErr(null);
201	          start(async () => {
202	            const res = await leaveOrg(orgId);
203	            if (res.error) setErr(res.error);
204	          });
205	        }}
206	      >
207	        {pending ? "…" : "Leave organization"}
208	      </button>
209	      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
210	    </div>
211	  );
212	}
213	
214	/* ---------------- Org card ---------------- */
215	
216	function OrgCard({ org }: { org: OrgView }) {
217	  return (
218	    <div className="card space-y-4">
219	      <div className="flex flex-wrap items-start justify-between gap-3">
220	        <div>
221	          <h3 className="flex items-center gap-2 font-semibold">
222	            {org.name}
223	            <Badge tone={roleTone(org.myRole)}>{org.myRole.toLowerCase()}</Badge>
224	          </h3>
225	          <p className="mt-1 text-xs text-slate-400">
226	            Owned by {org.ownerName} · {org.members.length} member
227	            {org.members.length === 1 ? "" : "s"} · created {org.createdAgo}
228	          </p>
229	        </div>
230	        {!org.isOwner && <LeaveButton orgId={org.id} />}
231	      </div>
232	
233	      <div className="table-wrap overflow-x-auto">
234	        <table className="table-shell min-w-[560px]">
235	          <thead>
236	            <tr>
237	              <th>Member</th>
238	              <th>Role</th>
239	              <th>Joined</th>
240	              {org.canAdminister && <th className="text-right">Actions</th>}
241	            </tr>
242	          </thead>
243	          <tbody>
244	            {org.members.map((m) => {
245	              const cols = org.canAdminister ? 4 : 3;
246	              // OWNER / ADMIN always have full access; only MEMBER / BILLING can
247	              // be constrained. Only admins see the editor.
248	              const fullAccess = m.isOwner || m.role === "ADMIN" || m.role === "OWNER";
249	              return (
250	                <Fragment key={m.userId}>
251	                  <tr>
252	                    <td>
253	                      <span className="font-medium">{m.name}</span>
254	                      <span className="ml-2 text-xs text-slate-500">{m.email}</span>
255	                    </td>
256	                    <td>
257	                      {org.canAdminister && !m.isOwner ? (
258	                        <RoleSelect orgId={org.id} member={m} />
259	                      ) : (
260	                        <Badge tone={roleTone(m.role)}>{m.role.toLowerCase()}</Badge>
261	                      )}
262	                    </td>
263	                    <td className="text-xs text-slate-400">{m.joinedAgo}</td>
264	                    {org.canAdminister && (
265	                      <td className="text-right">
266	                        {m.isOwner ? (
267	                          <span className="text-xs text-slate-500">owner</span>
268	                        ) : (
269	                          <RemoveButton orgId={org.id} member={m} />
270	                        )}
271	                      </td>
272	                    )}
