import { z } from "zod";

/**
 * Boot-time validation of critical environment variables.
 *
 * IMPORTANT: This never throws at import time — a missing var must not break
 * the build or crash a server component render. Instead `validateEnv()` returns
 * a structured result and logs a single clear warning listing what's missing.
 */

const envSchema = z.object({
  DATABASE_URL: z.string().min(1),
  AUTH_SECRET: z.string().min(1),
  PROXMOX_API_URL: z.string().min(1),
  PROXMOX_NODE: z.string().min(1),
  PROXMOX_TOKEN_ID: z.string().min(1),
  PROXMOX_TOKEN_SECRET: z.string().min(1),
});

export type EnvValidation = { ok: boolean; missing: string[] };

/**
 * Check that all critical env vars are present and non-empty.
 * Returns `{ ok, missing[] }` and logs a warning (never throws).
 */
export function validateEnv(): EnvValidation {
  const result = envSchema.safeParse(process.env);
  if (result.success) {
    return { ok: true, missing: [] };
  }
  // Collect the top-level keys that failed (missing or empty).
  const missing = Array.from(
    new Set(result.error.issues.map((i) => String(i.path[0])).filter(Boolean)),
  );
  console.warn(
    `[env] Missing or invalid critical environment variables: ${missing.join(", ")}. ` +
      `The app will continue to boot, but features depending on these will fail at runtime.`,
  );
  return { ok: false, missing };
}
