/**
 * Short-lived, encrypted authorization tokens for the in-portal web terminal.
 *
 * The browser never opens the terminal websocket with its session cookie —
 * instead the app mints a 60-second, single-purpose token (this module) that
 * encodes exactly {userId, serverId}. The standalone PTY backend
 * (terminal-server/index.ts) verifies that token before it will SSH anywhere.
 *
 * The token is a JWE (encrypted, A256GCM) — mirroring the VNC console ticket in
 * app/api/console/[serverId]/route.ts — so its contents are opaque to the
 * browser and cannot be tampered with. The symmetric key is DERIVED from the
 * app's AUTH_SECRET the same way the console does, with a terminal-specific
 * salt, so the web app and the terminal backend agree on the key with no extra
 * shared secret to configure.
 *
 * Plain server-side module (no "use server"): importable by both the Next route
 * handler and the tsx-run terminal backend.
 */
import { createHash } from "node:crypto";
import { EncryptJWT, jwtDecrypt } from "jose";

/** Lifetime of a minted terminal token. It only needs to survive the round-trip
 * from `POST /api/terminal/token` to the websocket upgrade. */
export const TERMINAL_TOKEN_TTL_SECONDS = 60;

/** What every terminal token carries. Nothing sensitive — just who + which VM. */
export type TerminalTokenClaims = {
  userId: string;
  serverId: string;
};

/**
 * 256-bit symmetric key for the terminal JWE, derived from AUTH_SECRET. The
 * terminal backend derives the identical key the same way, so no separate
 * secret needs distributing. Distinct salt from the console key so a console
 * ticket can never be replayed as a terminal token (or vice-versa).
 */
function terminalKey(): Uint8Array {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set");
  return new Uint8Array(createHash("sha256").update(`nxeon-terminal:${secret}`).digest());
}

/** Mint an encrypted, 60-second terminal token for {userId, serverId}. */
export async function signTerminalToken(claims: TerminalTokenClaims): Promise<string> {
  return new EncryptJWT({ userId: claims.userId, serverId: claims.serverId })
    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
    .setIssuedAt()
    .setExpirationTime(`${TERMINAL_TOKEN_TTL_SECONDS}s`)
    .encrypt(terminalKey());
}

/**
 * Verify + decrypt a terminal token. Returns the claims, or throws if the token
 * is missing, malformed, tampered with, or expired (jwtDecrypt enforces `exp`).
 */
export async function verifyTerminalToken(token: string): Promise<TerminalTokenClaims> {
  const { payload } = await jwtDecrypt(token, terminalKey());
  const userId = payload.userId;
  const serverId = payload.serverId;
  if (typeof userId !== "string" || typeof serverId !== "string" || !userId || !serverId) {
    throw new Error("terminal token missing userId/serverId");
  }
  return { userId, serverId };
}

